// Calculate base risk score
let riskScore = 20;

// Tor usage frequency (experience factor)
if (torUsage === 'first-time') riskScore += 25;
else if (torUsage === 'occasionally') riskScore += 15;
else if (torUsage === 'monthly') riskScore += 10;
else if (torUsage === 'weekly') riskScore += 5;

// Tor configuration
if (torConfiguration === 'outdated') riskScore += 30;
else if (torConfiguration === 'modified') riskScore += 20;
else if (torConfiguration === 'default') riskScore += 5;
else if (torConfiguration === 'hardened') riskScore -= 10;

// VPN usage
if (vpnUsage === 'unsure') riskScore += 15;
else if (vpnUsage === 'vpn-over-tor') riskScore += 10;
else if (vpnUsage === 'tor-over-vpn') riskScore += 5;

// Dark web marketplace access
if (darkWebAccess === 'frequently') riskScore += 35;
else if (darkWebAccess === 'occasionally') riskScore += 25;
else if (darkWebAccess === 'browsing-only') riskScore += 10;

// Personal information sharing
if (personalInfo === 'frequently') riskScore += 40;
else if (personalInfo === 'sometimes') riskScore += 25;
else if (personalInfo === 'minimal') riskScore += 10;

// File downloads
if (downloadFiles) riskScore += 20;

// JavaScript settings
if (javascriptEnabled === 'enabled') riskScore += 25;
else if (javascriptEnabled === 'default') riskScore += 5;
else if (javascriptEnabled === 'disabled') riskScore -= 5;

// Operating system
if (operatingSystem === 'tails') riskScore -= 20;
else if (operatingSystem === 'linux') riskScore -= 5;
else if (operatingSystem === 'mac') riskScore += 10;
else if (operatingSystem === 'windows') riskScore += 15;

// Ensure score is within bounds
const overallRisk = Math.max(0, Math.min(100, riskScore));
const anonymityScore = Math.max(0, 100 - overallRisk);

// Determine risk level
let riskLevel;
if (overallRisk <= 20) riskLevel = 'A';
else if (overallRisk <= 35) riskLevel = 'B';
else if (overallRisk <= 50) riskLevel = 'C';
else if (overallRisk <= 70) riskLevel = 'D';
else riskLevel = 'F';

// Generate recommendations
let recommendations = [];
if (torConfiguration === 'outdated') recommendations.push('Update to the latest Tor browser version immediately');
if (torConfiguration === 'modified') recommendations.push('Remove all browser extensions and use default Tor settings');
if (personalInfo !== 'never') recommendations.push('Never share personal information while using Tor');
if (downloadFiles) recommendations.push('Avoid downloading files through Tor to prevent IP leaks');
if (javascriptEnabled === 'enabled') recommendations.push('Disable JavaScript or use default Tor security settings');
if (operatingSystem === 'windows') recommendations.push('Consider using Tails OS or Linux for better security');
if (darkWebAccess === 'frequently') recommendations.push('Limit dark web marketplace access and understand legal risks');
if (vpnUsage === 'unsure') recommendations.push('Research proper VPN configuration or use Tor alone');
recommendations.push('Consider using Incognito Browser for additional privacy layers in regular browsing');

return {
  overallRisk: Math.round(overallRisk),
  riskLevel: riskLevel,
  anonymityScore: Math.round(anonymityScore),
  recommendations: recommendations.slice(0, 5).join('; ')
};
